import { recordEgress } from "../../../../../../lib/admin_engine.ts";

const { COLD_START_LATENCY_MS, JITTER_MS_MIN, JITTER_MS_MAX } = DATABRICKS_PARAMS;

// Graph-declared polling semantics per state:
//   RUNNING — Polling by response_code + statement_id: while the statement runs, response_code is absent; on completion response_code carries the HTTP-equivalent status. statement_id keys the poll URL.

// The graph declares RUNNING as the observed Databricks polling state
// (response_code absent while running, present on completion); the simulator
// models the pre-RUNNING cold start as QUEUED and completion as
// SUCCEEDED/FAILED.
export type PollState = "QUEUED" | "RUNNING" | "SUCCEEDED" | "FAILED";

const TERMINAL: Record<PollState, boolean> = {
  QUEUED: false,
  "RUNNING": false,
  SUCCEEDED: true,
  FAILED: true,
};

export interface PollResult {
  statement_id: string;
  status: { state: PollState; response_code?: number };
  elapsedMs: number;
  terminal: boolean;
}

// ---------------------------------------------------------------------------
// SUCCEEDED result pagination (gap S3/J3). First page inline on the terminal
// poll; opaque nextPageToken (statement_id + page index) only while rowCount
// exceeds pageSize; GET ?page=N (or ?pageToken=<token>) returns that slice.
// ---------------------------------------------------------------------------
const PAGE_SIZE = 10000; // rows per page (graph: pageSize, e.g. 10k)
const ROW_COUNT = 25000; // fabricated synthetic result cardinality per statement
const LAST_PAGE = Math.ceil(ROW_COUNT / PAGE_SIZE);

/** FNV-1a 32-bit over seed:statement_id:rowIndex — deterministic row content
 * from the sim seed; identical row index is byte-identical on every page. */
function rowCell(statementId: string, rowIndex: number, salt: string): string {
  let h = 0x811c9dc5;
  const input = `${JITTER_SEED}:${statementId}:${salt}:${rowIndex}`;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, "0");
}

function rowFor(statementId: string, rowIndex: number): string[] {
  return [String(rowIndex), `id-${rowCell(statementId, rowIndex, "id")}`, `v-${rowCell(statementId, rowIndex, "v")}`];
}

function buildPage(statementId: string, page: number) {
  const start = (page - 1) * PAGE_SIZE;
  const end = Math.min((page - 1) * PAGE_SIZE + PAGE_SIZE, ROW_COUNT);
  const data: string[][] = [];
  for (let i = start; i < end; i++) data.push(rowFor(statementId, i));
  return {
    rowCount: ROW_COUNT,
    pageSize: PAGE_SIZE,
    page,
    data,
    nextPageToken: page < LAST_PAGE ? `${statementId}:page:${page + 1}` : undefined,
  };
}

/** Opaque nextPageToken -> page index (token form: "<id>:page:<n>"). */
function pageFromToken(token: string): number {
  const parts = token.split(":page:");
  const n = Number(parts[parts.length - 1]);
  if (!Number.isInteger(n) || n < 1) throw new Error(`malformed pageToken: ${token}`);
  return n;
}

export async function GET(
  request: Request,
  ctx: { params: Promise<{ statement_id: string }> },
): Promise<Response> {
  const { statement_id } = await ctx.params;
  // Timeline anchor: the submit time recorded by the submit route; an
  // un-submitted handle starts its timeline at first observation.
  const submitMs = submitTimeOf(statement_id) ?? recordSubmitTime(statement_id);
  const elapsedMs = Date.now() - submitMs;
  // Deterministic across-restart determinism: the fabricated cardinality is
  // constant (ROW_COUNT), so page count is stable for every statement.
  const jitterMs = handleJitterMs(statement_id, JITTER_MS_MIN, JITTER_MS_MAX);
  const state: PollState = pollStateFor(elapsedMs, jitterMs, COLD_START_LATENCY_MS);

  if (state !== "SUCCEEDED") {
    const result: PollResult = {
      statement_id,
      status: { state, response_code: undefined },
      elapsedMs,
      terminal: TERMINAL[state],
    };
    return new Response(JSON.stringify(result), { status: 200 });
  }

  // SUCCEEDED: terminal poll carries the inline first page; ?page=N /
  // ?pageToken=<opaque token> returns that slice of the synthetic result.
  const url = new URL(request.url);
  const token = url.searchParams.get("pageToken");
  const pageParam = url.searchParams.get("page");
  let page = 1;
  if (token !== null) page = pageFromToken(token);
  else if (pageParam !== null) page = Number(pageParam);
  const result = buildPage(statement_id, page);
  const bodyText = JSON.stringify({
    statement_id,
    status: { state, response_code: 200 },
    elapsedMs,
    terminal: true,
    result: { rowCount: result.rowCount, pageSize: result.pageSize, page: result.page, data: result.data, nextPageToken: result.nextPageToken },
  });
  // LEDGER BRIDGE: terminal observation — charge the real egress bytes of
  // this response to the handle's submit-time record.
  recordEgress(statement_id, Buffer.byteLength(bodyText));
  return new Response(bodyText, { status: 200 });
}
